// Real glyph coverage: the font file's cmap (+ GSUB / presentation forms) decides, not the family name.
// Test fonts are generated by test/helpers/mini-font.ts (no third-party font data).
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { analyze } from "../src/engine.ts";
import { BUNDLED, ASSET_FONT_DIR } from "../src/fonts.ts";
import { fileCoverage, dataUriCoverage, familyCoverage, verifiedClass } from "../src/glyphs.ts";
import { fixRemotion } from "../src/remotion/project.ts";
import { miniFont, LATIN, ARABIC_LETTERS } from "./helpers/mini-font.ts";

const PRES = [0xfe8e, 0xfe91, 0xfe92, 0xfedf, 0xfee0, 0xfeea];
const tmp = () => fs.mkdtempSync(path.join(os.tmpdir(), "hz-glyphs-"));
const fonts = (d: string) => {
  fs.mkdirSync(path.join(d, "fonts"), { recursive: true });
  fs.writeFileSync(path.join(d, "fonts", "latin.ttf"), miniFont("Brand Latin", LATIN));
  fs.writeFileSync(path.join(d, "fonts", "arabic.ttf"), miniFont("Brand Arabic", [...LATIN, ...ARABIC_LETTERS, ...PRES]));
  fs.writeFileSync(path.join(d, "fonts", "nojoin.ttf"), miniFont("Brand NoJoin", [...LATIN, ...ARABIC_LETTERS]));
  fs.writeFileSync(path.join(d, "fonts", "partial.ttf"), miniFont("Brand Partial", [...LATIN, ...ARABIC_LETTERS.slice(0, 12)]));
  return d;
};
const page = (face: string, family: string) =>
  `<html lang="ar" dir="rtl"><head><style>${face}h1{font-family:${family},sans-serif}</style></head><body><h1>عنوان الحلقة</h1></body></html>`;
const hz = (html: string, baseDir?: string, code = "HZ09") => analyze(html, { baseDir }).issues.filter((i) => i.code === code);

test("every bundled OFL font really covers Arabic and joins through OpenType init/medi/fina", () => {
  for (const b of Object.values(BUNDLED)) for (const f of b.faces) {
    const c = fileCoverage(path.join(ASSET_FONT_DIR, f.file));
    assert.ok(c, f.file);
    assert.equal(c!.letters, c!.total, `${f.file} missing ${c!.missing.join(" ")}`);
    assert.equal(c!.joins, "gsub", f.file);
  }
});

test("fileCoverage: Latin-only, Arabic with presentation forms, letters without joining, partial", () => {
  const d = fonts(tmp());
  const at = (f: string) => fileCoverage(path.join(d, "fonts", f))!;
  assert.deepEqual([at("latin.ttf").letters, at("latin.ttf").arabic], [0, false]);
  assert.deepEqual([at("arabic.ttf").arabic, at("arabic.ttf").joins], [true, "presentation-forms"]);
  assert.deepEqual([at("nojoin.ttf").arabic, at("nojoin.ttf").joins], [true, "none"]);
  assert.deepEqual([at("partial.ttf").arabic, at("partial.ttf").letters], [false, 12]);
  assert.equal(fileCoverage(path.join(d, "fonts", "missing.ttf")), null);
  assert.equal(fileCoverage(path.join(ASSET_FONT_DIR, "OFL-cairo.txt")), null, "only font files are opened");
});

test("HTML: an unknown custom family whose file covers Arabic is trusted (was an 'unknown family' HZ09 info)", () => {
  const d = fonts(tmp());
  const html = page(`@font-face{font-family:"Brand";src:url(./fonts/arabic.ttf) format("truetype")}`, `"Brand"`);
  assert.equal(hz(html, d).length, 0);
  // the web tool has no files to read: still the cautious info
  assert.deepEqual(hz(html).map((i) => i.severity), ["info"]);
});

test("HTML: a custom family whose file has no Arabic is a warning naming the file (not an 'unknown' info)", () => {
  const d = fonts(tmp());
  const [i] = hz(page(`@font-face{font-family:"Brand";src:url("fonts/latin.ttf")}`, `"Brand"`), d);
  assert.equal(i.severity, "warning");
  assert.match(i.message.en, /checked the font file: latin\.ttf has no Arabic glyphs \(0\/36 letters/);
  assert.ok(i.fixable, "the OFL fallback is still offered");
});

test("HTML: the file beats the name: 'Cairo' served from a Latin-only file, letters without joining forms, partial coverage", () => {
  const d = fonts(tmp());
  assert.equal(hz(page(`@font-face{font-family:Cairo;src:url(fonts/latin.ttf)}`, "Cairo"), d)[0]?.severity, "warning");
  assert.match(hz(page(`@font-face{font-family:Brand;src:url(fonts/nojoin.ttf)}`, "Brand"), d)[0].message.en, /no joining forms .*isolated/);
  // partial.ttf has ء آ أ ؤ إ ئ ا ب ة ت ث ج: "عنوان الحلقة" needs letters it lacks
  assert.match(hz(page(`@font-face{font-family:Brand;src:url(fonts/partial.ttf)}`, "Brand"), d)[0].message.en, /partial\.ttf lacks ح ع ق ل ن و used in this text \(12\/36 Arabic letters\)/);
});

test("HTML: a font subset to the page's own letters is fine (glyphhanger / Google Fonts text=)", () => {
  const d = tmp();
  const text = "باب ثابت";
  const cps = [...new Set([...text.replace(/\s/g, "")].map((c) => c.codePointAt(0)!))];
  fs.mkdirSync(path.join(d, "fonts"));
  fs.writeFileSync(path.join(d, "fonts", "subset.ttf"), miniFont("Subset", [0x20, ...cps, ...PRES]));
  const html = `<html lang="ar" dir="rtl"><head><style>@font-face{font-family:Sub;src:url(fonts/subset.ttf)}h1{font-family:Sub}</style></head><body><h1>${text}</h1></body></html>`;
  assert.equal(hz(html, d).length, 0);
  assert.match(hz(html.replace("باب ثابت", "باب جديد"), d)[0].message.en, /subset\.ttf lacks ج د ي used in this text/);
});

test("HTML: subsets: a local Latin subset plus a remote face is not a verdict (the remote face may carry Arabic)", () => {
  const d = fonts(tmp());
  const face = `@font-face{font-family:Cairo;src:url(fonts/latin.ttf);unicode-range:U+0000-00FF}@font-face{font-family:Cairo;src:url(https://fonts.example/cairo-arabic.woff2);unicode-range:U+0600-06FF}`;
  assert.equal(hz(page(face, "Cairo"), d).length, 0);
  // two local subsets: the family covers what any face covers
  const two = `@font-face{font-family:Brand;src:url(fonts/latin.ttf)}@font-face{font-family:Brand;src:url(fonts/arabic.ttf);unicode-range:U+0600-06FF}`;
  assert.equal(hz(page(two, "Brand"), d).length, 0);
});

test("HTML: embedded data: fonts are checked even in the web tool (no files)", () => {
  const b64 = (cps: number[]) => `data:font/ttf;base64,${miniFont("Embedded", cps).toString("base64")}`;
  assert.equal(dataUriCoverage(b64([...ARABIC_LETTERS, ...PRES]))!.arabic, true);
  assert.equal(hz(page(`@font-face{font-family:Emb;src:url(${b64([...ARABIC_LETTERS, ...PRES])})}`, "Emb")).length, 0);
  assert.equal(hz(page(`@font-face{font-family:Emb;src:url("${b64(LATIN)}")}`, "Emb"))[0].severity, "warning");
});

test("HTML: a verified Thmanyah file still gets the licensing finding (licensing goes by the name)", () => {
  const d = fonts(tmp());
  const html = page(`@font-face{font-family:"Thmanyah Sans";src:url(fonts/arabic.ttf)}`, `"Thmanyah Sans"`);
  assert.equal(hz(html, d).length, 0);
  assert.equal(hz(html, d, "HZ10").length, 1);
});

test("HTML: faces in a linked stylesheet resolve relative to the stylesheet", () => {
  const d = fonts(tmp());
  fs.mkdirSync(path.join(d, "css"));
  fs.writeFileSync(path.join(d, "css", "type.css"), `@font-face{font-family:Brand;src:url(../fonts/latin.ttf)}`);
  const html = `<html lang="ar" dir="rtl"><head><link rel="stylesheet" href="css/type.css"><style>h1{font-family:Brand}</style></head><body><h1>عنوان</h1></body></html>`;
  assert.match(hz(html, d)[0].message.en, /latin\.ttf has no Arabic glyphs/);
});

test("verifiedClass: generic/system untouched; incomplete negative keeps the name", () => {
  const latin = { cov: { family: "", file: "x.ttf", letters: 0, total: 36, arabic: false, joins: "none" as const, missing: [] }, complete: false };
  assert.equal(verifiedClass("arabic-ofl", latin), "arabic-ofl");
  assert.equal(verifiedClass("arabic-ofl", { ...latin, complete: true }), "no-arabic");
  assert.equal(verifiedClass("generic", { ...latin, complete: true }), "generic");
  assert.equal(familyCoverage([]), null);
});

test("Remotion project: FontFace + staticFile() files are read: Latin-only 'Brand' gets the fallback, Arabic 'Saudi'-style file is trusted", async () => {
  const mk = (file: "latin.ttf" | "arabic.ttf") => {
    const d = tmp();
    fs.writeFileSync(path.join(d, "package.json"), JSON.stringify({ name: "x", dependencies: { remotion: "4" } }));
    fonts(path.join(d, "public"));
    fs.mkdirSync(path.join(d, "src"));
    fs.writeFileSync(path.join(d, "src", "fonts.ts"), `import { staticFile } from "remotion";\nconst f = new FontFace("Brand", \`url(\${staticFile("fonts/${file}")})\`);\nf.load().then(() => document.fonts.add(f));\n`);
    fs.writeFileSync(path.join(d, "src", "Title.tsx"), `import "./fonts";\nexport const Title = () => <h1 style={{ fontFamily: "Brand" }}>عنوان الحلقة</h1>;\n`);
    return d;
  };
  const codes = (r: any) => r.files.flatMap((f: any) => [...(f.changes ?? []), ...(f.issues ?? [])]).filter((c: any) => c.code === "HZ09").map((c: any) => c.en ?? c.message?.en);
  const bad = codes(await fixRemotion(mk("latin.ttf"), { write: false } as any));
  assert.ok(bad.some((m: string) => /checked the font file: latin\.ttf has no Arabic glyphs/.test(m)), JSON.stringify(bad));
  assert.deepEqual(codes(await fixRemotion(mk("arabic.ttf"), { write: false } as any)), []);
});
